html_escape<-function(s) {
  s<-gsub('&','&amp;',as.character(s),fixed=TRUE);s<-gsub('<','&lt;',s,fixed=TRUE);gsub('>','&gt;',s,fixed=TRUE)
}
html_table<-function(d) {
  d<-as.data.frame(d)
  for(j in seq_along(d))if(is.numeric(d[[j]]))d[[j]]<-format(signif(d[[j]],4),trim=TRUE)
  paste0('<div class="table"><table><thead><tr>',paste0('<th>',html_escape(names(d)),'</th>',collapse=''),'</tr></thead><tbody>',paste(apply(d,1,function(row)paste0('<tr>',paste0('<td>',html_escape(row),'</td>',collapse=''),'</tr>')),collapse=''),'</tbody></table></div>')
}
write_report<-function(x,e,p,cfg) {
  efx<-e$effects;de<-e$de$table;keep<-efx$primary_eligible
  summary<-list(generated_at=format(Sys.time(),'%Y-%m-%d %H:%M:%S %z'),raw_genes=nrow(x$counts),libraries=ncol(x$counts),core_libraries=nrow(x$core),parental_libraries=sum(x$meta$treatment=='PARENTAL'),primary_genes=sum(keep),unique_symbols=nrow(e$mapping),descriptive_candidates=sum(efx$descriptive_candidate),exploratory_DE_BH05=sum(de$FDR<.05),exploratory_DE_higher=sum(de$FDR<.05 & de$logFC>0),exploratory_DE_lower=sum(de$FDR<.05 & de$logFC<0),mitochondrial_sensitivity_BH05=sum(e$sensitivity$table$FDR<.05),PC1_percent=100*e$pca_variance[1],PC2_percent=100*e$pca_variance[2],RLE_Spearman=cor(efx$mean_difference[keep],efx$RLE_mean_difference[keep],method='spearman'),assignment_min=min(e$qc$assigned_fraction),assignment_max=max(e$qc$assigned_fraction),mitochondrial_fraction_min=min(e$qc$mitochondrial_fraction),mitochondrial_fraction_max=max(e$qc$mitochondrial_fraction),pairing='uncertain_not_used',independent_derivation='uncertain_not_claimed',count_unit='reads',enrichment_complete=!is.null(p))
  if(!is.null(p)) summary<-c(summary,list(msigdb_version=cfg$msigdb_version,resource_sets=nrow(p$coverage),pathways_tested=nrow(p$fgsea),fgsea_global_BH05=sum(p$fgsea$BH_across_collections<.05,na.rm=TRUE),camera_global_BH05=sum(p$camera$BH_across_collections<.05,na.rm=TRUE),camera_estimated_correlation_BH05=sum(p$camera_sensitivity$BH_across_collections<.05,na.rm=TRUE),TFs_tested=nrow(p$tf)))
  jsonlite::write_json(summary,'provenance/run_summary.json',pretty=TRUE,auto_unbox=TRUE)
  ydepletion<-100*(1-e$pairs$Y_LOY_CPM/e$pairs$Y_CTRL_CPM)
  pc_mito<-cor(e$pca$PC1,e$qc$mitochondrial_fraction[match(x$core$sample_key,e$qc$sample_key)],method='spearman')
  lines<-c('# A549 LOY versus sgCTRL: reprocessed analysis','',paste('Generated:',summary$generated_at),'',
    sprintf('The analysis includes %s count features across 11 libraries: four LOY, four sgCTRL and three parental. The primary eight-library comparison retains %s autosomal/non-PAR X genes. Parentals are excluded from its filtering, normalization and effect estimates.',format(summary$raw_genes,big.mark=','),format(summary$primary_genes,big.mark=',')),'',
    'The author confirmed that pairing and population-derivation history are uncertain. Numerical sample suffixes are treated as identifiers. Primary effects are unpaired differences between group means; there is no passage-paired model, temporal-replication claim or assumption of independently generated populations. Voom-limma P values are exploratory and conditional on independent model residuals.','',
    sprintf('PC1 and PC2 explain %.1f%% and %.1f%% of core expression variation. Assignment fractions range from %.1f%% to %.1f%%; mitochondrial content ranges from %.1f%% to %.1f%% of assigned reads. These are descriptive QC measurements, not diagnoses of RNA quality.',summary$PC1_percent,summary$PC2_percent,100*summary$assignment_min,100*summary$assignment_max,100*summary$mitochondrial_fraction_min,100*summary$mitochondrial_fraction_max),'',
    sprintf('There are %s descriptive candidates with absolute mean logCPM difference >= 0.5 and consistent direction under all eight one-sample omissions. The exploratory unpaired voom analysis yields %s genes at BH < 0.05 (%s higher and %s lower in LOY). The mitochondrial-covariate sensitivity yields %s; this data-derived adjustment is not the primary model.',summary$descriptive_candidates,summary$exploratory_DE_BH05,summary$exploratory_DE_higher,summary$exploratory_DE_lower,summary$mitochondrial_sensitivity_BH05),'',
    'Gene-level effects use exact GENCODE v49 IDs. Filtering follows the HT1080 settings (filterByExpr min.count 10, min.total.count 15); TMM is estimated on expressed autosomes/non-PAR X in the eight core samples. The same exposures quantify Y, PAR and mitochondrial branches. PCA uses all retained genes, centring without variance scaling. No outcome-based sample exclusion or batch subtraction is applied.','',
    'The featureCounts v2.1.1 headers contain -p but no --countReadPairs: original units are reads. Counts were checked against every source table and assignment summary; no alignment, recounting, or silent halving of counts was performed. All original inputs and previous reports are unchanged.','',
    sprintf('Across the eight displayed Y-linked genes, mean normalized CPM is %.1f%% to %.1f%% lower in LOY than sgCTRL. The corresponding X-linked partners show mean logCPM differences from %.2f to %.2f. These measurements support Y-linked transcript depletion but do not establish functional compensation.',min(ydepletion),max(ydepletion),min(e$pairs$X_mean_difference),max(e$pairs$X_mean_difference)),'',
    sprintf('PC1 is strongly associated with mitochondrial read fraction (Spearman rho = %.2f). This association does not identify whether composition variation is technical or biological. The lack of genes passing primary BH < 0.05 is not evidence that all non-Y expression is unchanged; within-group variability and the unresolved sampling design limit inference.',pc_mito),'',
    'Y-linked RNA depletion is not a measurement of chromosome structure or the fraction of Y-negative cells. X/Y paralog RNA responses and length-normalised sums are expression proxies, not tests of functional buffering. PAR RNA is not Y-specific. DNA/RNA coordinate integration is deferred because genome assemblies and specimen correspondence require verification.','',
    sprintf('RLE-versus-TMM effect-rank correlation is %.4f. The complete one-sample-omission, low-prior, and mitochondrial-covariate sensitivities are retained, including weak or discordant results.',summary$RLE_Spearman),'')
  if(!is.null(p))lines<-c(lines,sprintf('Using the same frozen MSigDB %s resources as HT1080, %s of %s sets are eligible (15–500 represented symbols). Global BH < 0.05 identifies %s fgsea sets and %s fixed-correlation CAMERA sets; estimated-correlation CAMERA identifies %s. Each method has its own global correction across all eligible sets. The report shows complete Hallmark results and full resource coverage, not only significant pathways.',summary$msigdb_version,summary$pathways_tested,summary$resource_sets,summary$fgsea_global_BH05,summary$camera_global_BH05,summary$camera_estimated_correlation_BH05),'',
    sprintf('CollecTRI ULM evaluates %s represented regulator target patterns. PROGENy footprint summaries use frozen weights. These analyses generate transcriptional hypotheses and do not directly measure regulator activity or establish a causal LOY mechanism.',summary$TFs_tested),'')
  if(!is.null(p))lines<-c(lines,sprintf('Numerical diagnostics: %s fgsea sets have P values at the configured 1e-10 reporting floor; %s have unavailable log2-error estimates and P values above the floor. The latter may have overestimated P values according to fgsea diagnostics. Full P values, log2err and floor flags are retained. Values at the floor are not exact probabilities. Enrichment can arise from distributed ranked effects even when no individual primary gene passes BH; it is not independent confirmation of a reproducible population effect.',sum(p$fgsea$p_at_lower_bound,na.rm=TRUE),sum(is.na(p$fgsea$log2err)&p$fgsea$pval>cfg$fgsea_eps,na.rm=TRUE)),'')
  if(!is.null(p) && summary$camera_global_BH05>0 && summary$camera_estimated_correlation_BH05==0)lines<-c(lines,'Pathway significance is strongly sensitive to the inter-gene correlation assumption: no sets retain global BH < 0.05 with estimated nonnegative CAMERA correlations. The fixed-correlation and preranked results should therefore be treated as hypothesis-generating patterns, with their sensitivity visible alongside any biological interpretation.','')
  par<-as.data.frame(data.table::fread('outputs/tables/DE_PAR_secondary_voom.csv'))
  parhits<-par[par$BH_PAR_family<.05,]
  lines<-c(lines,sprintf('PAR follow-up: PAR genes were excluded from the primary test family, so zero primary significant genes does not mean PAR expression is unchanged. A secondary inclusive voom fit covers all expressed nuclear genes with the original core TMM scaling. Among %s expressed PAR-overlapping features, %s pass BH < 0.05 within the PAR family and %s pass BH < 0.05 across all expressed nuclear genes. Both corrections are reported. This follow-up was added in response to the author\'s PAR question after the primary results, and remains exploratory.',nrow(par),nrow(parhits),sum(par$BH_all_expressed_nuclear_genes<.05)),'',
    'Multiple PAR1 transcripts are lower in LOY: the descriptive mean-CPM reductions are approximately 41% for PLCXD1, 36% for GTPBP6, 35% for SLC25A6 and 51% for CSF2RA. Each retains a negative group-mean logCPM difference under all one-sample omissions. These are observed expression changes, not a direct estimate of chromosome copy number. PAR-overlapping features that cross a region boundary are flagged in the full table.','')
  lines<-c(lines,'The HT1080 comparison uses exact shared primary gene IDs and the saved two-window HT1080 descriptive effects. Different sample designs, retained Y material and population histories limit mechanistic interpretation of agreement or disagreement. HT1080-specific HDAC, chromatin-atlas, rescue and nicotinic-receptor follow-ups were not transferred as assumptions about A549.','',
    'Reproduce from this directory with R 4.5.2: `Rscript --vanilla run.R`. `--core-only` performs expression/QC without enrichment; `--enrichment-only` resumes after verifying saved core inputs; `--report-only` renders saved results. Code hashes, package versions, input hashes, resource hashes and scientific validation are stored in provenance.','',
    'References: [Subread counting semantics](https://subread.sourceforge.net/featureCounts.html); [limma User Guide](https://www.bioconductor.org/packages/release/bioc/vignettes/limma/inst/doc/usersguide.pdf).')
  writeLines(lines,'outputs/report/analysis.md')
  body<-c('<h1>A549 LOY versus sgCTRL</h1>',paste0('<p>',html_escape(lines[!grepl('^#|^$',lines)]),'</p>'))
  top<-head(de[order(de$FDR),c('gene_name','gene_id','logFC','FDR','mean_difference')],20)
  body<-c(body,'<h2>Leading exploratory gene-level results</h2>',html_table(top),'<p><a href="../tables/DE_unpaired_voom_exploratory.csv">Complete gene-level results</a> | <a href="../tables/A549_LOY_vs_sgCTRL_all_gene_effects.csv">All descriptive effects</a> | <a href="../tables/analysis_status.csv">Analysis scope and unresolved design</a></p>')
  body<-c(body,'<h2>Secondary PAR analysis</h2>',html_table(par[order(par$PValue),c('gene_name','PAR_region','PAR_boundary_overlap','logFC','CPM_percent_change','PValue','BH_PAR_family','BH_all_expressed_nuclear_genes')]),'<p><a href="../tables/DE_PAR_secondary_voom.csv">Complete PAR test table</a></p>')
  if(!is.null(p)) {
    topfg<-head(p$fgsea[order(p$fgsea$BH_across_collections),c('pathway','collection','NES','BH_across_collections')],20)
    body<-c(body,'<h2>Enrichment across all collections</h2>',html_table(p$summary),html_table(topfg),'<p><a href="../tables/fgsea_all_collections.csv">Full fgsea results</a> | <a href="../tables/camera_all_collections.csv">Full CAMERA results</a> | <a href="../tables/collectri_ULM_effect_signatures.csv">CollecTRI results</a></p>')
  }
  figs<-list.files('outputs/figures',pattern='\\.png$',full.names=TRUE)
  sources<-list(Fig09_PAR_expression='PAR_selected_gene_sample_abundance;DE_PAR_secondary_voom',Fig01_library_QC='library_QC',Fig02_PCA_core='PCA_core;PCA_variance_core',Fig03_unpaired_DE='DE_unpaired_voom_exploratory',Fig04_expression_effects='A549_LOY_vs_sgCTRL_primary_effects',Fig05_Y_expression='XY_paralog_sample_abundance',Fig06_XY_paralogs='XY_paralog_effects_and_length_proxy',Fig07_Hallmark_enrichment='fgsea_all_collections',Fig08_TF_target_patterns='collectri_ULM_effect_signatures',SuppFig01_PCA_parental_context='PCA_context_all11',SuppFig02_cross_line_effects='A549_HT1080_effect_comparison',SuppFig03_leave_one_out='A549_LOY_vs_sgCTRL_primary_effects',SuppFig04_PCA_PC1_PC3_core='PCA_core;PCA_variance_core')
  stems<-sub('\\.png$','',basename(figs))
  manifest<-data.frame(figure=stems,source_tables=vapply(stems,function(z)paste0('../tables/',strsplit(sources[[z]],';',fixed=TRUE)[[1]],'.csv',collapse=';'),character(1)),caption=paste0('../captions/',stems,'.md'))
  data.table::fwrite(manifest,'outputs/source_data/figure_manifest.csv')
  for(f in figs) {
    stem<-sub('\\.png$','',basename(f));caption<-readLines(paste0('outputs/captions/',stem,'.md'),warn=FALSE)
    body<-c(body,paste0('<h2>',html_escape(gsub('_',' ',stem)),'</h2><img src="data:image/png;base64,',base64enc::base64encode(f),'" alt="',html_escape(stem),'"/><p>',html_escape(paste(caption[-c(1,2)],collapse=' ')),'</p><p><a href="../figures/',stem,'.pdf">PDF</a> | <a href="../figures/',stem,'.svg">SVG</a></p>'))
  }
  html<-c('<!doctype html><html><head><meta charset="utf-8"><title>A549 RNA-seq reprocessing</title><style>body{max-width:1100px;margin:40px auto;padding:0 24px;font-family:Arial,sans-serif;line-height:1.55;color:#22303b}h1,h2{color:#175b80}img{max-width:100%;height:auto}.table{overflow-x:auto}table{border-collapse:collapse;font-size:13px}th,td{padding:7px;border-bottom:1px solid #ddd;text-align:left}th{background:#edf3f7}a{color:#0072b2}</style></head><body>',body,'</body></html>')
  writeLines(html,'outputs/report/analysis.html')
  invisible(summary)
}
